package com.ramka.domain.usecaseimport com.ramka.domain.util.OfflineSignalTrackerimport kotlinx.coroutines.runBlockingimport org.junit.Assert.assertEqualsimport org.junit.Assert.assertFalseimport org.junit.Assert.assertTrueimport org.junit.Testclass OfflineFileSignalTest {    private var clock = 1_000_000L    private val tracker = OfflineSignalTracker(now = { clock }, cooldownMillis = 5 * 60 * 1000L)    private val sent = mutableListOf<Pair<String, String>>()    private var failSend = false    private val signal = OfflineFileSignal(tracker) { contactId, text ->        if (failSend) throw IllegalStateException("нет контакта")        sent += contactId to text    }    @Test fun firstFailureSendsFixedTextAndMarksFileNotified() = runBlocking {        assertTrue(signal("c1", "f1"))        assertEquals(listOf("c1" to OfflineFileSignal.TEXT), sent)        assertEquals("Вам пытаются отправить файл. Откройте приложение, чтобы получить его.", OfflineFileSignal.TEXT)        assertTrue("f1" in tracker.notifiedFiles.value)    }    @Test fun retryOfSameFileDoesNotSendAgainEvenAfterCooldown() = runBlocking {        assertTrue(signal("c1", "f1"))        clock += 10 * 60 * 1000L        assertFalse(signal("c1", "f1"))        assertEquals(1, sent.size)    }    @Test fun otherFileOfSameContactWithinFiveMinutesIsSuppressed() = runBlocking {        assertTrue(signal("c1", "f1"))        clock += 4 * 60 * 1000L        assertFalse(signal("c1", "f2"))        assertFalse("f2" in tracker.notifiedFiles.value)        assertEquals(1, sent.size)    }    @Test fun otherFileOfSameContactAfterFiveMinutesIsSent() = runBlocking {        assertTrue(signal("c1", "f1"))        clock += 5 * 60 * 1000L        assertTrue(signal("c1", "f2"))        assertEquals(2, sent.size)    }    @Test fun differentContactsDoNotBlockEachOther() = runBlocking {        assertTrue(signal("c1", "f1"))        assertTrue(signal("c2", "f2"))        assertEquals(2, sent.size)    }    @Test fun failedSendReleasesTheWindowAndLeavesFileUnmarked() = runBlocking {        failSend = true        assertFalse(signal("c1", "f1"))        assertFalse("f1" in tracker.notifiedFiles.value)        failSend = false        assertTrue(signal("c1", "f1")) // окно не «съедено» неудачной попыткой        assertEquals(1, sent.size)    }    @Test fun clockMovedBackwardsKeepsWindowClosed() = runBlocking {        assertTrue(signal("c1", "f1"))        clock -= 60_000L        assertFalse(signal("c1", "f2"))    }}